// Desktop storage host — MAIN process side of ticket F5 (approach #3).
// better-sqlite3-multiple-ciphers is a native module and safeStorage is main-process-only, so the
// actual DB lives HERE, not in the sandboxed renderer. The renderer's StorageProvider (see
// src/storage/electronStorage.ts) proxies q/run/exec/persist over the `sutra:db` IPC channel; this
// module runs the real desktop adapter and answers those calls.
//
// ── SQLCipher key handling (parity with the Android Keystore invariant db.ts documents) ──────────
// The passphrase is generated by a CSPRNG and sealed with Electron safeStorage (Keychain on macOS /
// DPAPI on Windows / libsecret on Linux). The SEALED bytes are written to a file under userData; the
// PLAINTEXT key only ever exists transiently in this main-process module's memory and is applied to
// SQLCipher via openDesktopStorage({ key }). It is NEVER handed to the renderer and NEVER written to
// localStorage / WebView storage — preserving the same single-source-of-truth invariant as device.
import { app, ipcMain, safeStorage } from "electron";
import { randomBytes } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { openDesktopStorage } from "../src/storage/desktopAdapter";
import type { StorageProvider } from "../src/storage/StorageProvider";

const KEY_FILE = "sutra.key"; // safeStorage-sealed ciphertext, NOT a plaintext key
const DB_FILE = "sutra.db";

/** Load the sealed key from userData, or mint + seal a fresh one on first run. Returns the plaintext
 *  hex key, which stays only in this process's memory. */
function provisionKey(): string {
  const keyPath = join(app.getPath("userData"), KEY_FILE);
  if (existsSync(keyPath) && safeStorage.isEncryptionAvailable()) {
    try {
      return safeStorage.decryptString(readFileSync(keyPath));
    } catch {
      /* corrupt/rotated OS key — fall through and re-mint (a fresh DB will be created) */
    }
  }
  const key = randomBytes(32).toString("hex");
  if (safeStorage.isEncryptionAvailable()) {
    writeFileSync(keyPath, safeStorage.encryptString(key));
  }
  return key;
}

let storage: StorageProvider | null = null;
let openError: string | null = null;

/** Marker the renderer recognises to show a precise "rebuild the database engine" message. */
export const DB_UNAVAILABLE = "SUTRA_DB_UNAVAILABLE";

/** Human fix for the most common failure: the native module was compiled for Node, not Electron
 *  (e.g. `npm install` ran without the postinstall rebuild). */
function describe(e: unknown): string {
  const msg = String((e as any)?.message ?? e);
  if (/NODE_MODULE_VERSION|compiled against a different Node\.js version|was compiled against/i.test(msg)) {
    return "The local database engine was built for Node.js instead of Electron. In the frontend folder run: npm run rebuild:electron — then restart Sutra.";
  }
  if (/Cannot find module|could not locate the bindings/i.test(msg)) {
    return "The local database engine isn't installed. In the frontend folder run: npm install && npm run rebuild:electron — then restart Sutra.";
  }
  return `Sutra couldn't open its local database: ${msg.split("\n")[0]}`;
}

/** Open the encrypted desktop DB once and register the IPC handler the renderer proxy calls.
 *  Never throws: on failure the handler answers every query with a clear, actionable error (and the
 *  returned message is shown once by main.ts), so the window still opens instead of silently dying. */
export function initDesktopStorage(): string | null {
  if (storage || openError) return openError;
  try {
    storage = openDesktopStorage({
      filename: join(app.getPath("userData"), DB_FILE),
      key: provisionKey(),
    });
  } catch (e) {
    openError = describe(e);
    console.error("[sutra] database unavailable:", e);
  }

  // One typed channel; the renderer never sees the key, only rows. Errors are surfaced as rejections.
  ipcMain.handle("sutra:db", async (_e, op: string, sql: string, params: any[]) => {
    const s = storage;
    if (!s) throw new Error(`${DB_UNAVAILABLE}: ${openError}`);
    switch (op) {
      case "q":
        return s.q(sql, params);
      case "run":
        return s.run(sql, params);
      case "exec":
        return s.exec(sql);
      case "persist":
        return s.persist();
      default:
        throw new Error(`unknown sutra:db op: ${op}`);
    }
  });
  return openError;
}
